function loadRepository(n){const e=n.dataset.owner,r=n.dataset.repo;fetch(`https://api.github.com/repos/${e}/${r}`,{headers:{Accept:"application/vnd.github+json"}}).then(n=>{if(!n.ok)throw new Error(n.status);return n.json()}).then(e=>renderRepository(n,e)).catch(()=>renderError(n,e,r))}function renderRepository(n,e){const r=e.language||"",t=languageColor(r);n.innerHTML=`\n        <div class="github-repo-card__title">\n            📌\n            <a href="${e.html_url}"\n               target="_blank"\n               rel="noopener noreferrer">\n                ${e.name}\n            </a>\n        </div>\n\n        <div class="github-repo-card__description">\n          ${renderEmoji(e.description)}\n        </div>\n\n        <div class="github-repo-card__footer">\n            <span class="github-repo-card__language">\n                <span class="github-language-dot"\n                      style="background:${t}"></span>\n                ${r||"Unknown"}\n            </span>\n\n            <span>⭐ ${e.stargazers_count}</span>\n        </div>\n    `}function renderError(n,e,r){n.innerHTML=`\n        <div class="github-repo-card--error">\n            <div class="github-repo-card__title">\n                📌 ${r}\n            </div>\n\n            <div class="github-repo-card__description">\n                Failed to fetch repository details:<br>\n                ${e}/${r}\n            </div>\n        </div>\n    `}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".github-repo-card").forEach(loadRepository)});const LANGUAGE_COLORS={Scala:"#dc322f",Go:"#00add8",Rust:"#dea584",Java:"#b07219",TypeScript:"#3178c6"};function languageColor(n){return LANGUAGE_COLORS[n]||"#8b949e"}const EMOJI={tiger:"🐯",wrench:"🔧",leaves:"🍃",paperclip:"📎",file_folder:"📁"};function renderEmoji(n){return n?n.replace(/:([a-z0-9_+-]+):/g,(n,e)=>EMOJI[e]||n):""}